<?php
$t=isset($_GET['id'])?sql('SELECT * FROM tasks WHERE id=? AND deletedAt IS NULL',[positiveId($_GET['id'])])->fetch():null;
if(isset($_GET['id'])&&!$t)throw new DomainException('Subtarefa não encontrada.');
$clientId=$t?(int)$t['clientId']:positiveId($_GET['client']??null);$c=client($clientId);if($c['deletedAt']){requireAdmin($user);?>
<a href="?client=<?=$clientId?>#subtasks" class="back-link"><?=icon('arrow')?> <?=h($c['nome'])?></a><section class="panel form-panel"><span class="eyebrow">CLIENTE ARQUIVADO</span><h1><?=h($t['title']??'Subtarefa')?></h1><p class="description-text"><?=nl2br(h($t['description']??''))?></p><p class="muted">Prazo: <?=h(shortDate($t['dueDate']??null))?> · <?=!empty($t['completedAt'])?'Concluída':'Pendente'?></p><p class="notice">Restaure o cliente para editar suas subtarefas.</p></section>
<?php return;}
?>
<a href="?client=<?=$clientId?>#subtasks" class="back-link"><?=icon('arrow')?> <?=h($c['nome'])?></a><div class="page-heading"><div><span class="eyebrow">PRÓXIMO PASSO</span><h1><?=$t?'Editar subtarefa':'Nova subtarefa'?></h1><p>Uma ação clara, com responsável e prazo.</p></div><?php if($t):?><form method="post" data-confirm="Remover esta subtarefa? A ação ficará registrada no histórico do cliente."><?php formAction('task_delete',$t);?><button class="button danger">Remover subtarefa</button></form><?php endif;?></div><section class="panel form-panel"><form method="post" class="form-stack"><?php formAction('task_save',$t);?><input type="hidden" name="clientId" value="<?=$clientId?>"><?php if(!$t):?><input type="hidden" name="requestToken" value="<?=h(postVal('requestToken',bin2hex(random_bytes(32))))?>"><?php endif;?><label>O que precisa ser feito?<input name="title" required maxlength="240" value="<?=h(postVal('title',$t['title']??''))?>" placeholder="Ex.: alinhar o próximo acompanhamento"></label><label>Descrição<textarea name="description" rows="5" maxlength="5000"><?=h(postVal('description',$t['description']??''))?></textarea></label><div class="form-grid"><label>Responsável<select name="assigneeId"><?php userOptions($users,postVal('assigneeId',$t['assigneeId']??$user['id']));?></select></label><label>Prazo<input type="date" name="dueDate" value="<?=h(postVal('dueDate',$t['dueDate']??''))?>"></label><label>Prioridade<select name="priority"><?php options(PRIORITIES,postVal('priority',$t['priority']??'normal'));?></select></label></div><div class="form-actions"><button class="button primary">Salvar subtarefa</button><a href="?client=<?=$clientId?>#subtasks" class="button secondary">Cancelar</a></div></form></section>
